+        tcx.hir_crate_items(())
+            .definitions()
+            .map(|ld| ld.to_def_id())
+            .filter(|&m| {
+                tcx.def_kind(m) == DefKind::Mod && sys_modules().contains(&tcx.def_path_str(m))
+            })
+            .collect()
+    });
