/// impl of one can hand out a `&Foo` over C-owned memory.
const REF_FORMING: &[&str] = &[
    "Deref", "DerefMut", "AsRef", "AsMut", "Borrow", "BorrowMut", "Index", "IndexMut",
];

/// True if `tr` is one of std's `REF_FORMING` traits.
fn is_ref_forming(tcx: TyCtxt<'_>, tr: DefId) -> bool {
    is_std_crate(tcx, tr) && REF_FORMING.contains(&tcx.item_name(tr).as_str())
}

/// The types of the crates `--sys-crates` names (`ty.ffibox.sys`): every struct
/// they declare, the ones a `-sys` declaration puts behind a raw
/// pointer, and of those the ones the crate's compiled code names at all and
/// the ones a cell's `CCell::C` names -- how much of the C the bindings expose
/// by pointer the crate uses, and has given a cell.
///
/// Counted from the crate that declares cells, once: the inventory is the
/// `-sys` crates', and a second crate scanning beside it would count it again.
/// Types of another crate have no visibility of this one's, so the counts are
/// scalars. Enums are out: a C enum is used through its generated constants
/// and takes no cell, whether bindgen writes it as a Rust enum or as a
/// newtype over its integer (`is_newtype_enum`). Unions are out too, but not
/// what they hold: a union's fields are declarations like a struct's, and a
/// union behind a pointer puts its members there (`sys_pointees`).
///
/// The fns they declare likewise (`fn.ffibox.sys`), with the ones the crate
/// names, and the crate's own fns annotated as standing in for one
/// (`fn.ffibox.wrapper`) or for a field (`ty.ffibox.wrapper.fields`): each
/// `#[doc(alias)]` resolved against the inventory, the only record of what a
/// wrapper wraps. A fn is named bare; a field by its member path, which
/// `member_path` walks through the declared layouts. An alias that names
/// neither, a type's included, is no wrapper of a fn or a field, and counts
/// nowhere here.
fn count_sys_types<'tcx>(
    tcx: TyCtxt<'tcx>,
    ptr: &mut PtrTally,
    sites: &mut Sites,
    cs: &HashSet<DefId>,
) {
    let mut types: Vec<DefId> = Vec::new();
    let mut fns: Vec<DefId> = Vec::new();
    // What an alias can name: a function, or a struct's or union's field.
    let mut fn_names: HashSet<String> = HashSet::new();
    // The structs and unions a member path can start from, by name: their
    // own, or a type alias's that resolves to one.
    let mut roots: HashMap<String, DefId> = HashMap::new();
    let mut behind_ptr: HashSet<DefId> = HashSet::new();
    // One declaration of the bindings: a type, a fn, an alias or a static.
    let mut take = |kind: DefKind, did: DefId| {
        let mut decl = |t: Ty<'tcx>| sys_pointees(tcx, t, &mut behind_ptr);
        match kind {
            DefKind::Struct if is_newtype_enum(tcx, did) => {}
            DefKind::Struct | DefKind::Union => {
                if kind == DefKind::Struct && !types.contains(&did) {
                    types.push(did);
                }
                roots.insert(tcx.item_name(did).to_string(), did);
                for f in tcx.adt_def(did).all_fields() {
                    decl(tcx.type_of(f.did).instantiate_identity().skip_norm_wip());
                }
            }
            DefKind::Fn => {
                if !fns.contains(&did) {
                    fns.push(did);
                    fn_names.insert(tcx.item_name(did).to_string());
                }
                let sig = tcx.fn_sig(did).skip_binder().skip_binder();
                for t in sig.inputs_and_output {
                    decl(t);
                }
            }
            DefKind::TyAlias | DefKind::Static { .. } => {
                let t = tcx.type_of(did).instantiate_identity().skip_norm_wip();
                if kind == DefKind::TyAlias {
                    if let Some(adt) = member_adt(tcx, t) {
                        roots.entry(tcx.item_name(did).to_string()).or_insert(adt);
                    }
                }
                decl(t);
            }
            _ => {}
        }
    };
    for &cnum in tcx.crates(()) {
        if !sys_crates().contains(tcx.crate_name(cnum).as_str()) {
            continue;
        }
        let mut modules = vec![cnum.as_def_id()];
        let mut seen = HashSet::new();
        while let Some(m) = modules.pop() {
            if !seen.insert(m) {
                continue;
            }
            for child in tcx.module_children(m) {
                let Res::Def(kind, did) = child.res else { continue };
                // A re-export of another crate's item is that crate's.
                if did.krate != cnum {
                    continue;
                }
                if kind == DefKind::Mod {
                    modules.push(did);
                } else {
                    take(kind, did);
                }
            }
        }
    }
    // Bindings that are a module of the scanned crate: its own definitions
    // below a named module, a re-export being another item's.
    if !sys_modules().is_empty() {
        for ld in tcx.hir_crate_items(()).definitions() {
            let did = ld.to_def_id();
            if in_sys_module(tcx, did) {
                take(tcx.def_kind(did), did);
            }
        }
    }
    drop(take);
    let mut bump = |k: &str, did: DefId| {
        *ptr.entry(k.to_string()).or_default() += 1;
        sites.add(k.to_string(), span_site(tcx, tcx.def_span(did)));
    };
    let named = named_defs(tcx);
    for did in types {
        bump("ty.ffibox.sys.total", did);
        if behind_ptr.contains(&did) {
            bump("ty.ffibox.sys.of_which.raw_ptr_in_sys.total", did);
            if named.contains(&did) {
                bump("ty.ffibox.sys.of_which.raw_ptr_in_sys.of_which.used", did);
            }
            if cs.contains(&did) {
                bump("ty.ffibox.sys.of_which.raw_ptr_in_sys.of_which.wrapped", did);
            }
        }
    }
    for did in fns {
        bump("fn.ffibox.sys.total", did);
        if named.contains(&did) {
            bump("fn.ffibox.sys.of_which.used", did);
        }
    }

    // The annotations: each alias on one of the crate's fns that names a
    // `-sys` fn or field, once per alias and item, so a C function forked
    // into several variants counts once per variant, and once in `unique`.
    let mut seen_fns: HashSet<String> = HashSet::new();
    let mut seen_fields: HashSet<String> = HashSet::new();
    for ld in tcx.hir_crate_items(()).definitions() {
        if in_sys_module(tcx, ld.to_def_id()) {
            continue;
        }
        let did = ld.to_def_id();
        if !matches!(tcx.def_kind(did), DefKind::Fn | DefKind::AssocFn)
            || in_generated_file(tcx, tcx.def_span(did))
        {
            continue;
        }
        for alias in doc_aliases(tcx, ld) {
            if fn_names.contains(&alias) {
                bump(&format!("fn.ffibox.wrapper.{}", wrapper_arm(tcx, did)), did);
                if seen_fns.insert(alias) {
                    bump("fn.ffibox.wrapper.of_which.unique", did);
                }
            } else if member_path(tcx, &roots, &alias) {
                bump("ty.ffibox.wrapper.fields.total", did);
                if seen_fields.insert(alias) {
                    bump("ty.ffibox.wrapper.fields.of_which.unique", did);
                }
            }
        }
    }
}

/// Whether `path`, `<root>.<member>{.<member>}`, names a field of a `-sys`
/// struct or union: from the root, each step a member of the one before,
/// through the layouts the `-sys` crate declares. The path names only what
/// is named in C, so the steps are matched as bindgen writes them:
///
/// - a member named after a Rust keyword or primitive carries bindgen's
///   trailing `_` (C's `type` is `type_`);
/// - an unnamed member, a C11 anonymous struct or union, is no step: bindgen
///   declares it as `__bindgen_anon_<n>`, and its members are looked up
///   through it, as C accesses them;
/// - an anonymous type held by a named member is bindgen's
///   `<parent>__bindgen_ty_<n>`, reached through that member; and
/// - an array's elements have no name, so an array member's next step is a
///   member of its element type.
///
/// A step that is not a member, or that goes on from a member that holds no
/// struct or union, resolves nothing.
fn member_path(tcx: TyCtxt<'_>, roots: &HashMap<String, DefId>, path: &str) -> bool {
    let mut steps = path.split('.');
    let Some(mut adt) = steps.next().and_then(|r| roots.get(r)).copied() else {
        return false;
    };
    let mut steps = steps.peekable();
    if steps.peek().is_none() {
        return false;
    }
    while let Some(step) = steps.next() {
        let Some(t) = member(tcx, adt, step) else { return false };
        if steps.peek().is_none() {
            return true;
        }
        let Some(next) = member_adt(tcx, t) else { return false };
        adt = next;
    }
    false
}

/// The type of the member `name` of the struct or union `adt`, as bindgen
/// declares it, looking through its unnamed members. A bitfield is no field
/// of bindgen's: it packs a run of them into `_bitfield_<n>` and declares a
/// getter of each one's name, whose return type the bitfield's is.
fn member<'tcx>(tcx: TyCtxt<'tcx>, adt: DefId, name: &str) -> Option<Ty<'tcx>> {
    let fields = &tcx.adt_def(adt).non_enum_variant().fields;
    let type_of = |f: &ty::FieldDef| tcx.type_of(f.did).instantiate_identity().skip_norm_wip();
    let escaped = format!("{name}_");
    let named = |n: &str| n == name || n == escaped;
    fields
        .iter()
        .find(|f| f.name.as_str() == name)
        .or_else(|| fields.iter().find(|f| f.name.as_str() == escaped))
        .map(type_of)
        .or_else(|| {
            if !fields.iter().any(|f| f.name.as_str().starts_with("_bitfield_")) {
                return None;
            }
            tcx.inherent_impls(adt)
                .iter()
                .flat_map(|&i| tcx.associated_item_def_ids(i).iter().copied())
                .find(|&d| tcx.def_kind(d) == DefKind::AssocFn && named(tcx.item_name(d).as_str()))
                .map(|d| tcx.fn_sig(d).skip_binder().skip_binder().output())
        })
        .or_else(|| {
            fields
                .iter()
                .filter(|f| f.name.as_str().starts_with("__bindgen_anon_"))
                .find_map(|f| member(tcx, member_adt(tcx, type_of(f))?, name))
        })
}

/// The struct or union a member of type `t` holds, by value or as an array's
/// elements; `ManuallyDrop`, which bindgen wraps a union's non-`Copy` members
/// in, is looked through.
fn member_adt(tcx: TyCtxt<'_>, mut t: Ty<'_>) -> Option<DefId> {
    loop {
        match t.kind() {
            ty::TyKind::Array(e, _) => t = *e,
            ty::TyKind::Adt(def, args) if def.is_manually_drop() => t = args.type_at(0),
            ty::TyKind::Adt(def, _) if def.is_struct() || def.is_union() => {
                return (!is_newtype_enum(tcx, def.did())).then_some(def.did());
            }
            _ => return None,
        }
    }
}

/// The names `#[doc(alias = "...")]` gives the item `ld`, every attribute's.
fn doc_aliases(tcx: TyCtxt<'_>, ld: rustc_span::def_id::LocalDefId) -> Vec<String> {
    let mut out = Vec::new();
    for a in tcx.hir_attrs(tcx.local_def_id_to_hir_id(ld)) {
        if let rustc_attr_ir::Attribute::Parsed(rustc_attr_ir::AttributeKind::Doc(d)) = a {
            out.extend(d.aliases.keys().map(ToString::to_string));
        }
    }
    out
}

/// Where an annotated fn sits (`fn.ffibox.wrapper`): a method of an ffibox
/// policy trait, by the trait (`policy.<trait>`); a method of any other
/// trait, its impl or its declaration (`other_trait`); or a free fn or an
/// inherent method (`non_trait`).
fn wrapper_arm(tcx: TyCtxt<'_>, did: DefId) -> String {
    if tcx.def_kind(did) == DefKind::AssocFn {
        let parent = tcx.parent(did);
        let tr = match tcx.def_kind(parent) {
            DefKind::Impl { of_trait: true } => Some(tcx.impl_trait_ref(parent).skip_binder().def_id),
            DefKind::Trait => Some(parent),
            _ => None,
        };
        if let Some(tr) = tr {
            let name = tcx.item_name(tr);
            if is_ffibox_crate(tcx, tr) && ffibox_trait_group(name.as_str()) == Some("policy") {
                return format!("policy.{name}");
            }
            return "other_trait".to_string();
        }
    }
    "non_trait".to_string()
}

