fn union_members<'tcx>(tcx: TyCtxt<'tcx>, t: Ty<'tcx>, out: &mut HashSet<DefId>) {
    match t.kind() {
        ty::TyKind::Adt(d, _) if d.is_union() => {
            for f in d.all_fields() {
                union_members(tcx, tcx.type_of(f.did).instantiate_identity().skip_norm_wip(), out);
            }
        }
        ty::TyKind::Adt(d, args)
            if is_std_crate(tcx, d.did()) && tcx.item_name(d.did()).as_str() == "ManuallyDrop" =>
        {
            for a in args.types() {
                union_members(tcx, a, out);
            }
        }
        ty::TyKind::Adt(d, _) => {
            out.insert(d.did());
        }
        ty::TyKind::Array(e, _) => union_members(tcx, *e, out),
        _ => {}
    }
}

/// A C enum as bindgen's `newtype_enum` writes it: a `#[repr(transparent)]`
/// struct over one integer, its variants associated constants. A C struct is
/// `#[repr(C)]`, so the shape does not catch one.
fn is_newtype_enum(tcx: TyCtxt<'_>, did: DefId) -> bool {
    let adt = tcx.adt_def(did);
    adt.repr().transparent()
        && adt.all_fields().count() == 1
        && adt.all_fields().all(|f| {
            tcx.type_of(f.did).instantiate_identity().skip_norm_wip().is_integral()
        })
}

/// The ADTs a `-sys` declaration's type puts behind a raw pointer, however
/// many pointers deep (`*mut *mut git_repository`). Unlike `raw_pointees` it
/// enters fn pointers: a callback typedef's parameters are the bindings'
/// declarations too, and C hands its objects to callbacks by pointer. A union
/// behind a pointer is not a type of its own here: the pointer reaches its
/// members (`union_members`).
fn sys_pointees<'tcx>(tcx: TyCtxt<'tcx>, t: Ty<'tcx>, out: &mut HashSet<DefId>) {
    let pointee = match t.kind() {
        ty::TyKind::RawPtr(p, _) => Some(*p),
        ty::TyKind::Adt(d, args) if is_raw_ptr_adt(tcx, d.did()) => args.types().next(),
        _ => None,
    };
    if let Some(mut p) = pointee {
        while let ty::TyKind::RawPtr(q, _) = p.kind() {
            p = *q;
        }
        union_members(tcx, p, out);
        return;
    }
    match t.kind() {
        ty::TyKind::FnPtr(sig, _) => {
            for t in sig.skip_binder().inputs_and_output {
                sys_pointees(tcx, t, out);
            }
        }
        ty::TyKind::Adt(_, args) => {
            for a in args.types() {
                sys_pointees(tcx, a, out);
            }
        }
        ty::TyKind::Ref(_, t, _) | ty::TyKind::Array(t, _) | ty::TyKind::Slice(t) => {
            sys_pointees(tcx, *t, out);
        }
        ty::TyKind::Tuple(ts) => {
            for t in ts.iter() {
                sys_pointees(tcx, t, out);
            }
        }
        _ => {}
    }
}

/// Where the crate's declarations mention a `CCell` layout newtype
/// (`ty.ffibox.wrapper.as`) or the raw C type it covers (`ty.ffibox.sys.as`),
/// each in one arm by the innermost holder above it: borrowed or owned, by std
/// or by ffibox, or held by value with nothing above it. They sit under
/// `ty.ffibox`, since every one of them reads ffibox's convention and none is
/// emitted without the flag.
///
/// MENTIONS, not types. One cell is named in many places and it is the places
/// that are actionable, so a cell named in twenty signatures counts twenty
/// times and `--sites` lists them. The alternative, a type population, washes
/// the signal out: nearly every cell has an `as_ref`, so `self_in_ref_accessor`
/// would cover nearly every borrowed cell and the mentions that are NOT
/// sanctioned -- the ones worth reading -- would not be recoverable by
/// subtracting it.
///
/// `by_val` is the cell held as a value: no holder above the mention, so the
/// bytes are Rust-owned storage that moves with whatever holds it. A C pointer
/// retained into it dangles, and no owner runs the C destructor -- the cases
/// ffibox's `CBox` and `CVal` exist for.
fn count_cell_mentions(tcx: TyCtxt<'_>, ptr: &mut PtrTally, sites: &mut Sites) {
    let types = cell_types(tcx);
    if types.cells.is_empty() {
        return;
    }
    count_sys_types(tcx, ptr, sites, &types.cs);
    let evis = tcx.effective_visibilities(());
    let mut mentions: Vec<Mention> = Vec::new();

    for ld in tcx.hir_crate_items(()).definitions() {
        if in_sys_module(tcx, ld.to_def_id()) {
            continue;
        }
        let did = ld.to_def_id();
        if !matches!(tcx.def_kind(did), DefKind::Struct | DefKind::Union)
            || in_generated_file(tcx, tcx.def_span(did))
        {
            continue;
        }
        let exported = did.as_local().is_some_and(|l| evis.is_exported(l));
        for f in tcx.adt_def(did).all_fields() {
            let ft = tcx.type_of(f.did).instantiate_identity().skip_norm_wip();
            let mut found = Vec::new();
            walk_shapes(tcx, ft, Shape::default(), &mut found);
            let reachable =
                exported && f.did.as_local().is_some_and(|l| evis.is_exported(l));
            let site = counter_site(tcx, tcx.def_span(f.did));
            for (did, shape) in found {
                mentions.push(Mention {
                    did,
                    shape,
                    field: true,
                    reachable,
                    self_in_ref_accessor: false,
                    self_in_trait_impl: false,
                    ref_forming: false,
                    site: site.clone(),
                });
            }
        }
    }

    // Signatures, over the same population `fn.*` counts: a foreign
    // declaration has no body, so it never reaches `hir_body_owners`, and the
    // C declarations in a `-sys` crate are not this crate's choices.
    for owner in tcx.hir_body_owners() {
        if in_sys_module(tcx, owner.to_def_id()) {
            continue;
        }
        let did = owner.to_def_id();
        if !matches!(tcx.def_kind(did), DefKind::Fn | DefKind::AssocFn) {
            continue;
        }
        let parent_kind = tcx.opt_parent(did).map(|p| tcx.def_kind(p));
        let trait_impl = matches!(parent_kind, Some(DefKind::Impl { of_trait: true }));
        // An `as_ref` / `as_mut` in an INHERENT impl, by name: a conversion
        // the convention did not name, such as an `as_c_ptr`, stays in the
        // remainder, which is the point of the share.
        let accessor = matches!(parent_kind, Some(DefKind::Impl { of_trait: false }))
            && tcx
                .opt_item_name(did)
                .is_some_and(|n| matches!(n.as_str(), "as_ref" | "as_mut"));
        // `self`, not input 0. A free-standing `fn as_ref(w: &Foo)` is a
        // borrow the author chose and no contract licenses, and only the
        // receiver's shape is a trait's doing.
        let has_self = matches!(parent_kind, Some(DefKind::Impl { .. }))
            && tcx.associated_item(did).is_method();
        let ref_forming = trait_impl
            && tcx.opt_parent(did).is_some_and(|parent| {
                is_ref_forming(tcx, tcx.impl_trait_ref(parent).skip_binder().def_id)
            });
        let reachable = did.as_local().is_some_and(|l| evis.is_exported(l));
        let site = counter_site(tcx, tcx.def_span(did));
        let sig = tcx.fn_sig(did).skip_binder().skip_binder();
        let mut positions: Vec<Ty<'_>> = sig.inputs().to_vec();
        positions.push(sig.output());
        for (i, t) in positions.iter().enumerate() {
            let mut found = Vec::new();
            walk_shapes(tcx, *t, Shape::default(), &mut found);
            for (did, shape) in found {
                mentions.push(Mention {
                    did,
                    shape,
                    field: false,
                    reachable,
                    self_in_ref_accessor: has_self && accessor && i == 0,
                    self_in_trait_impl: has_self && trait_impl && i == 0,
                    ref_forming: has_self && ref_forming && i == 0,
                    site: site.clone(),
                });
            }
        }
    }

    for m in &mentions {
        // Behind a pointer its holder manages, with nothing below it claiming
        // the storage or publishing a borrow: not a mention of this crate's.
        // The walk went through the pointer for the nested cases, and any of
        // them clears the flag.
        if m.shape.via_ptr {
            continue;
        }
        let tree = if types.cells.contains(&m.did) {
            "wrapper"
        } else if types.cs.contains(&m.did) {
            "sys"
        } else {
            continue;
        };
        let vis = if m.reachable { "pub" } else { "priv" };
        let mut bump = |k: String| {
            *ptr.entry(k.clone()).or_default() += 1;
            sites.add(k, m.site.clone());
        };
        // One arm per mention, by the innermost qualifier above it, and
        // where it sits, which `field` and `fn_sig` partition.
        let arm = match m.shape.held {
            Some((arm, whose)) => format!("{arm}.{whose}"),
            None => "by_val".to_string(),
        };
        let at = if m.field { "field" } else { "fn_sig" };
        let base = format!("ty.ffibox.{tree}.as.{arm}");
        bump(format!("{base}.{vis}"));
        bump(format!("{base}.of_which.{at}.{vis}"));
        // The two sanctioned borrows, so the rest subtracts: the RECEIVER of
        // an accessor and of a trait method stand on the same contract, that
        // nothing hands out a `&Foo` over C-owned memory. Which is what the
        // unsanctioned mentions would do, so the counter audits the premise
        // its own shares rest on.
        if arm == "borrowed.std" {
            if m.self_in_ref_accessor {
                bump(format!("{base}.of_which.self_in_ref_accessor.{vis}"));
            }
            if m.self_in_trait_impl {
                bump(format!("{base}.of_which.self_in_trait_impl.{vis}"));
                if m.ref_forming {
                    bump(format!(
                        "{base}.of_which.self_in_trait_impl.of_which.ref_forming.{vis}"));
                }
            }
        }
    }
}

