            for (did, shape) in found {
                mentions.push(Mention {
                    did,
                    shape,
                    field: false,
                    reachable,
                    self_in_ref_accessor: has_self && accessor && i == 0,
                    self_in_trait_impl: has_self && trait_impl && i == 0,
                    ref_forming: has_self && ref_forming && i == 0,
                    site: site.clone(),
                });
